    a = 2 * din - 3; b = a + 1
    hook, title, hm, m1, m2, ins = E[din]
    nxt = (f"चौपाई {a + 2} और {a + 3}" if din < 21 else "अंतिम दोहा")
    nxt_spoken = (f"चौपाई {NUM[a + 1]} और {NUM[a + 2]} का" if din < 21 else "आख़िरी दोहे का")
